stageCss:
#stage .pt-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .pt-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .pt-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .pt-mark svg{ width:25px; height:25px; }
#stage .pt-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .pt-sent{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .pt-sent b{
  color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:700;
  font-variant-numeric:tabular-nums;
}
#stage .pt-sent i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .pt-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(244,74,106,.55); background:rgba(244,74,106,.12);
  transition:border-color .3s ease, background .3s ease;
}
#stage .pt-health i{
  width:10px; height:10px; border-radius:50%; background:var(--danger);
  box-shadow:0 0 12px var(--danger); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .pt-health b{ color:var(--danger); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .pt-health.ok{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.1); }
#stage .pt-health.ok i{ background:var(--success); box-shadow:0 0 12px var(--success); }
#stage .pt-health.ok b{ color:var(--success); }

/* ============================= SCENE STACK ============================= */
#stage .pt-body{ position:relative; flex:1; min-height:0; }
#stage .pt-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .pt-sc.on{ opacity:1; transform:none; }
#stage .pt-sc.whip{ animation:pt-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .pt-flow{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* --------------------------------------------------------------- sender -- */
#stage .pt-sender{
  height:120px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
}
#stage .pt-sender.tight{ height:112px; }
#stage .pt-sender-ic{
  width:54px; height:54px; border-radius:15px; flex-shrink:0; font-size:27px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .pt-sender-t{ display:flex; flex-direction:column; gap:6px; min-width:0; }
#stage .pt-sender-t b{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .pt-sender-t i{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .pt-sender-b{
  margin-left:auto; flex-shrink:0; padding:8px 17px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(58,160,255,.5); background:rgba(58,160,255,.12); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:700; letter-spacing:1.2px;
}
#stage .pt-sender-b.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); }

/* ------------------------------------------------------------ the pipe --- */
#stage .pt-pipe{
  height:154px; flex-shrink:0; display:flex; flex-direction:column; gap:12px; justify-content:center;
  padding:16px 20px; border-radius:26px;
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.12), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(58,160,255,.45);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .pt-pipe.topic{
  border-color:rgba(63,185,80,.5);
  box-shadow:0 0 0 1px rgba(63,185,80,.2), 0 0 60px rgba(63,185,80,.12);
  background:radial-gradient(circle at 50% 0%, rgba(63,185,80,.12), transparent 62%), rgba(20,27,43,.6);
}
#stage .pt-pipe-h{ display:flex; align-items:center; gap:13px; }
#stage .pt-pipe-ic{
  width:46px; height:46px; border-radius:13px; flex-shrink:0; font-size:24px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.16); border:1.5px solid rgba(58,160,255,.4);
}
#stage .pt-pipe.topic .pt-pipe-ic{ background:rgba(63,185,80,.16); border-color:rgba(63,185,80,.4); }
#stage .pt-pipe-n{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .pt-pipe-b{
  margin-left:auto; padding:7px 15px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(58,160,255,.5); background:rgba(58,160,255,.12); color:var(--accent-1);
  font-family:var(--font-mono); font-size:17px; font-weight:700;
}
#stage .pt-pipe-b.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); }
#stage .pt-track{
  flex:1; min-height:0; display:flex; align-items:center; gap:9px;
  padding:0 14px; border-radius:16px; overflow:hidden;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border);
}
#stage .pt-m{
  padding:9px 14px; border-radius:11px; white-space:nowrap;
  background:rgba(34,211,238,.12); border:1.5px solid rgba(34,211,238,.45); color:var(--accent-cyan);
  font-family:var(--font-mono); font-size:18px; font-weight:700;
  transition:opacity .25s ease, background .25s ease, border-color .25s ease, color .25s ease;
}
#stage .pt-m.taken{ opacity:.22; }
#stage .pt-subs{
  flex:1; min-height:0; display:flex; align-items:center; gap:10px;
  padding:0 14px; border-radius:16px;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border);
}
#stage .pt-sub{
  flex:1; text-align:center; padding:10px 8px; border-radius:11px; white-space:nowrap;
  overflow:hidden; text-overflow:ellipsis;
  background:rgba(63,185,80,.1); border:1.5px solid rgba(63,185,80,.4); color:#bff0c4;
  font-family:var(--font-mono); font-size:17px; font-weight:600;
  transition:background .3s ease, border-color .3s ease, color .3s ease, opacity .3s ease;
}
#stage .pt-sub.muted{
  background:rgba(139,149,167,.08); border-color:rgba(139,149,167,.3); color:var(--text-dim);
  text-decoration:line-through; text-decoration-thickness:2px;
}

/* ------------------------------------------------------------- arrows ---- */
#stage .pt-arrows{
  position:relative; height:62px; flex-shrink:0;
  display:flex; align-items:center; justify-content:flex-start; gap:150px; padding-left:130px;
}
#stage .pt-arrows i{
  display:block; width:5px; height:26px; border-radius:3px;
  background:var(--accent-1); box-shadow:0 0 12px rgba(58,160,255,.5);
  animation:pt-drop 1.2s linear infinite;
}
#stage .pt-arrows i:nth-child(2){ animation-delay:.4s; }
#stage .pt-arrows i:nth-child(3){ animation-delay:.8s; }
/* Fan-out fires all three at once — that simultaneity is the whole idea. */
#stage .pt-arrows.fan i{ background:var(--success); box-shadow:0 0 12px rgba(63,185,80,.5); animation-delay:0s; }
#stage .pt-arrows-t{
  position:absolute; right:18px; top:50%; transform:translateY(-50%);
  color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; white-space:nowrap;
}

/* ------------------------------------------------------------- readers --- */
#stage .pt-readers{ flex:1; min-height:0; display:flex; align-items:center; gap:12px; }
#stage .pt-reader{
  flex:1; min-width:0; height:196px; display:flex; flex-direction:column; gap:10px; justify-content:center;
  padding:16px 16px; border-radius:22px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease, opacity .3s ease;
}
#stage .pt-reader.short{ border-color:rgba(244,74,106,.6); box-shadow:0 0 0 1px rgba(244,74,106,.2), 0 0 40px rgba(244,74,106,.14); }
#stage .pt-reader.full{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.2), 0 0 40px rgba(63,185,80,.12); }
#stage .pt-reader.muted{ opacity:.4; }
#stage .pt-r-h{ display:flex; align-items:center; gap:10px; }
#stage .pt-r-ic{ font-size:24px; flex-shrink:0; }
#stage .pt-r-h b{ color:#fff; font-family:var(--font-mono); font-size:20px; font-weight:700; white-space:nowrap; }
#stage .pt-r-n{ display:flex; align-items:baseline; gap:8px; }
#stage .pt-r-n b{
  color:#fff; font-family:var(--font-mono); font-size:38px; font-weight:800;
  font-variant-numeric:tabular-nums; line-height:1;
}
#stage .pt-r-n i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .pt-reader.short .pt-r-n b{ color:var(--danger); }
#stage .pt-reader.full .pt-r-n b{ color:var(--success); }
#stage .pt-r-s{
  color:var(--text-dim); font-family:var(--font-mono); font-size:16px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}

#stage .pt-note{
  height:112px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:22px;
  background:rgba(20,27,43,.6); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .pt-note.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.07); }
#stage .pt-note-ic{
  width:48px; height:48px; border-radius:14px; flex-shrink:0; font-size:25px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.3);
}
#stage .pt-note-t{ color:var(--text-primary); font-size:21px; font-weight:600; line-height:1.3; }

#stage .pt-code{
  height:118px; flex-shrink:0; display:flex; flex-direction:column; gap:5px; justify-content:center;
  padding:14px 20px; border-radius:20px;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border);
  opacity:.35; filter:saturate(.2);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease;
}
#stage .pt-code.on{ opacity:1; filter:none; border-color:rgba(63,185,80,.45); }
#stage .pt-code-l{
  color:var(--code-comment); font-family:var(--font-mono); font-size:17px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .pt-code-l:nth-child(2){ color:var(--code-plain); }
#stage .pt-code-l.diff{ color:var(--success); font-size:16px; }

#stage .pt-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .pt-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .pt-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .pt-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .pt-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .pt-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .pt-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ======================== SCENE 3 · QUEUE OR TOPIC ===================== */
#stage .pt-split{ display:flex; gap:16px; height:100%; }
#stage .pt-col{
  flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:16px;
  padding:26px 18px; border-radius:28px; text-align:center;
}
#stage .pt-col.q{ background:rgba(20,27,43,.6); border:2px solid rgba(58,160,255,.45); }
#stage .pt-col.t{
  background:radial-gradient(circle at 50% 0%, rgba(63,185,80,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(63,185,80,.5);
}
#stage .pt-col-h{ font-family:var(--font-mono); font-size:17px; font-weight:800; letter-spacing:1.2px; white-space:nowrap; }
#stage .pt-col.q .pt-col-h{ color:var(--accent-1); }
#stage .pt-col.t .pt-col-h{ color:var(--success); }
#stage .pt-col-ic{ font-size:54px; line-height:1; }
#stage .pt-col.t .pt-col-ic{ animation:msd-breathe 2.4s ease-in-out infinite; }
#stage .pt-col-list{ width:100%; display:flex; flex-direction:column; gap:10px; }
#stage .pt-row{
  padding:14px 10px; border-radius:13px;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-size:20px; font-weight:600; line-height:1.25;
}
#stage .pt-row b{ color:#fff; font-weight:800; }
#stage .pt-col-x{
  width:100%; padding:13px 10px; border-radius:14px;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.45); color:var(--accent-1);
  font-family:var(--font-mono); font-size:17px; font-weight:700; line-height:1.3;
}
#stage .pt-col-x.ok{ background:rgba(63,185,80,.12); border-color:rgba(63,185,80,.45); color:var(--success); }

/* ========================== SCENE 4 · THE PAYOFF ======================= */
#stage .pt-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .pt-badges{ display:flex; gap:20px; }
#stage .pt-badge{
  width:120px; height:120px; border-radius:34px; font-size:54px;
  display:flex; align-items:center; justify-content:center;
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .pt-badge.q{
  background:linear-gradient(160deg, rgba(58,160,255,.3), rgba(58,160,255,.1));
  border:2px solid rgba(58,160,255,.55);
  box-shadow:0 0 0 1px rgba(58,160,255,.24), 0 0 70px rgba(58,160,255,.24);
}
#stage .pt-badge.t{
  background:linear-gradient(160deg, rgba(63,185,80,.3), rgba(34,211,238,.12));
  border:2px solid rgba(63,185,80,.55);
  box-shadow:0 0 0 1px rgba(63,185,80,.24), 0 0 70px rgba(63,185,80,.24);
  animation-delay:.5s;
}
#stage .pt-badge-l{ color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:3px; }
#stage .pt-fin-h{ color:#fff; font-size:60px; font-weight:900; line-height:1.14; letter-spacing:-1.8px; }
#stage .pt-fin-h em{ font-style:normal; color:var(--success); }
#stage .pt-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .pt-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.42); color:var(--text-primary);
  font-size:21px; font-weight:700;
}
#stage .pt-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:860px;
  background:linear-gradient(90deg, rgba(58,160,255,.18), rgba(63,185,80,.16));
  border:1.5px solid rgba(63,185,80,.5); color:#fff;
  font-size:25px; font-weight:700; line-height:1.35;
}
#stage .pt-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes pt-drop{
  0%{ transform:translateY(-16px); opacity:0; }
  30%{ opacity:1; }
  100%{ transform:translateY(18px); opacity:0; }
}
@keyframes pt-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

