var PT = window.__PT || (window.__PT = {});

MSD.cls('.pt-sc', 'on', false);
MSD.cls('#pt-sc-queue', 'on', true);
MSD.q('#pt-app').textContent = 'OrderPlaced · who receives it?';
MSD.q('#pt-sent-n').textContent = '0';
MSD.cls('#pt-health', 'ok', false);
MSD.q('#pt-health-t').textContent = 'nobody yet';

MSD.q('#pt-sender-s').textContent = '6 orders in the last minute';
MSD.q('#pt-pipe-ic').textContent = '💬';
MSD.q('#pt-pipe-n').textContent = 'orders · queue';
MSD.q('#pt-pipe-b').textContent = 'one recipient per message';
MSD.cls('.pt-m', 'taken', false);
MSD.cls('.pt-reader', 'short', false);
MSD.cls('.pt-reader', 'full', false);
MSD.q('#pt-r-1-n').textContent = '0';
MSD.q('#pt-r-2-n').textContent = '0';
MSD.q('#pt-r-3-n').textContent = '0';
MSD.q('#pt-r-1-s').textContent = 'waiting';
MSD.q('#pt-r-2-s').textContent = 'waiting';
MSD.q('#pt-r-3-s').textContent = 'waiting';
MSD.q('#pt-arrows-t').textContent = 'they take turns, not copies';
MSD.cls('#pt-note', 'bad', false);
MSD.q('#pt-note-ic').textContent = '💬';
MSD.q('#pt-note-t').textContent = 'A queue is a direct message. One person reads it, and then it is gone.';
MSD.cls('#pt-strip', 'bad', false);
MSD.cls('#pt-strip', 'good', false);
MSD.q('#pt-strip-l').textContent = 'SEND';
MSD.q('#pt-strip-t').textContent = 'Three teams need this event. Watch what a queue actually gives them.';
MSD.hide('.pt-row');
MSD.hide('.pt-fin-p');
MSD.cls('#pt-code', 'on', false);
MSD.cls('.pt-sub', 'muted', false);

MSD.after(500, function(){ MSD.punch('#pt-sender', 1); MSD.sfx.blip(1); });
MSD.after(1100, function(){ MSD.punch('#pt-r-1', 2); });
MSD.after(1400, function(){ MSD.punch('#pt-r-2', 3); });
MSD.after(1700, function(){ MSD.punch('#pt-r-3', 4); MSD.sfx.blip(4); });

var PT = window.__PT;

MSD.cls('.pt-sc', 'on', false);
MSD.cls('#pt-sc-queue', 'on', true);
MSD.cls('.pt-m', 'taken', false);
MSD.cls('.pt-reader', 'short', false);
MSD.cls('#pt-note', 'bad', false);
MSD.q('#pt-note-ic').textContent = '💬';
MSD.q('#pt-note-t').textContent = 'A queue is a direct message. One person reads it, and then it is gone.';
MSD.cls('#pt-strip', 'bad', false);
MSD.q('#pt-strip-l').textContent = 'ONE';
MSD.q('#pt-strip-t').textContent = 'Completing a message deletes it. There is no second copy anywhere.';

MSD.after(400, function(){
  MSD.cls('#pt-m-1', 'taken', true);
  MSD.q('#pt-r-1-n').textContent = '1';
  MSD.q('#pt-r-1-s').textContent = 'took #1 · deleted';
  MSD.q('#pt-sent-n').textContent = '1';
  MSD.punch('#pt-r-1', 1);
  MSD.sfx.blip(1);
});
MSD.after(1400, function(){
  MSD.q('#pt-r-2-s').textContent = 'never saw #1';
  MSD.q('#pt-r-3-s').textContent = 'never saw #1';
  MSD.q('#pt-health-t').textContent = '1 of 3 teams';
  MSD.punch('#pt-r-2', 3);
  MSD.punch('#pt-r-3', 4);
  MSD.sfx.error();
});
MSD.after(2300, function(){
  MSD.q('#pt-note-t').textContent = 'Same as a DM: the other two are not muted, they were never in the conversation.';
  MSD.punch('#pt-note', 5);
});

var PT = window.__PT;

MSD.cls('.pt-sc', 'on', false);
MSD.cls('#pt-sc-queue', 'on', true);
MSD.cls('.pt-m', 'taken', false);
MSD.q('#pt-r-1-n').textContent = '0';
MSD.q('#pt-r-2-n').textContent = '0';
MSD.q('#pt-r-3-n').textContent = '0';
MSD.q('#pt-sent-n').textContent = '0';
MSD.q('#pt-r-1-s').textContent = 'receiving';
MSD.q('#pt-r-2-s').textContent = 'receiving';
MSD.q('#pt-r-3-s').textContent = 'receiving';
MSD.cls('#pt-strip', 'good', false);
MSD.cls('#pt-strip', 'bad', true);
MSD.q('#pt-strip-l').textContent = 'COMPETING';
MSD.q('#pt-strip-t').textContent = 'Every message still goes to exactly one of them. It just rotates.';

// Six messages dealt round-robin: the counters landing on 2/2/2 is the
// bug, stated as arithmetic.
var order = [1, 2, 3, 1, 2, 3];
var got = [0, 0, 0];
order.forEach(function(who, i){
  MSD.after(300 + i * 330, function(){
    MSD.cls('#pt-m-' + (i + 1), 'taken', true);
    got[who - 1]++;
    MSD.q('#pt-r-' + who + '-n').textContent = String(got[who - 1]);
